INSERT  IGNORE INTO `oils` (`id`, `name`, `origin`, `benefits`, `suitable_for`, `is_active`, `created_at`, `updated_at`) VALUES (1,'橄欖油','Olive Oil','橄欖油富含單元不飽和脂肪酸（油酸）與多酚類抗氧化物，有助降低壞膽固醇、保護心血管健康，並具抗發炎作用。適量食用還能幫助維持血糖穩定與皮膚健康。','橄欖油是從油橄欖果實中冷壓萃取而成的天然植物油，被譽為「液體黃金」。它源自地中海地區，已有數千年的歷史，是地中海飲食的重要核心。根據酸度和加工方式，分為特級初榨橄欖油（Extra Virgin）、初榨橄欖油和精製橄欖油等，其中特級初榨橄欖油保留最完整的風味與營養。橄欖油呈現金黃至綠色，帶有果香、草本或辛辣的獨特風味，適合生食、烹飪或沙拉淋醬。',1,'2026-05-27 09:48:57','2026-09-23 08:58:29');
INSERT  IGNORE INTO `oils` (`id`, `name`, `origin`, `benefits`, `suitable_for`, `is_active`, `created_at`, `updated_at`) VALUES (2,'棕櫚油','Palm Oil','棕櫚油富含維生素A原（β-胡蘿蔔素）與維生素E（生育酚），有助提供抗氧化保護並支持視力健康。適量攝取可提供穩定能量，但因飽和脂肪比例高，過量食用可能增加心血管負擔，建議適度使用。','棕櫚油是從油棕果實中萃取而得的植物油，主要產地為馬來西亞、印尼等東南亞國家，是全球產量最大的食用油之一。它分為粗棕櫚油與精煉棕櫚油，常見於加工食品、烘焙、油炸、零食及日常料理中，因其穩定性高、氧化慢且成本低廉而被廣泛使用。棕櫚油呈現橙紅色至淡黃色，具有輕微的堅果香氣，飽和脂肪含量較高，在室溫下為半固態。',1,'2026-05-27 09:55:33','2026-09-23 08:58:29');
INSERT  IGNORE INTO `oils` (`id`, `name`, `origin`, `benefits`, `suitable_for`, `is_active`, `created_at`, `updated_at`) VALUES (3,'椰子油','Coconut Oil','椰子油富含月桂酸等中鏈脂肪酸，能快速提供能量，並具有一定抗菌、抗病毒作用，有助提升免疫力與改善皮膚乾燥。適量食用可能幫助代謝與體重管理，但因飽和脂肪含量高，建議勿過量，以免影響心血管健康。','椰子油是從成熟椰子果肉中萃取而得的植物油，主要產地為菲律賓、印尼、印度等熱帶地區。它富含中鏈脂肪酸（MCTs），在室溫下呈現白色固態，溫度升高後會融化成透明液體，具有淡淡的椰香味。椰子油分為初榨椰子油（Virgin Coconut Oil）和精煉椰子油，前者保留較多天然風味與營養，適合生食或低溫烹飪；後者則較無味且穩定，常用於高溫油炸或加工食品。椰子油廣泛應用於料理、烘焙、護膚及護髮產品。',1,'2026-05-27 10:09:15','2026-09-23 08:58:29');
INSERT  IGNORE INTO `oils` (`id`, `name`, `origin`, `benefits`, `suitable_for`, `is_active`, `created_at`, `updated_at`) VALUES (4,'甜杏仁油','Sweet Almond Oil','甜杏仁油含有豐富的維生素E與抗氧化物，有助滋潤皮膚、改善乾燥與細紋，並提供良好的保濕與修護效果。適量食用可補充健康脂肪，有助維持心血管健康與皮膚彈性。','甜杏仁油是從甜杏仁（非苦杏仁）果仁中冷壓萃取而成的植物油，質地輕盈、顏色淡黃且帶有溫和的堅果香氣。它廣泛應用於烹飪、烘焙，也常作為護膚與按摩油使用，因其性質溫和、不易致敏，適合敏感肌膚。甜杏仁油富含油酸等單元不飽和脂肪酸，穩定性佳，適合中低溫烹調或生食淋醬。相較於其他堅果油，它的味道較為柔和，不會搶走食材原味。',1,'2026-05-28 10:29:12','2026-09-23 08:58:29');
INSERT  IGNORE INTO `oils` (`id`, `name`, `origin`, `benefits`, `suitable_for`, `is_active`, `created_at`, `updated_at`) VALUES (5,'乳油木果油','Shea Butter Oil','乳油木果油具有極佳的保濕、滋潤與修護能力，能有效改善皮膚乾燥、粗糙及細紋，同時具抗炎作用，有助舒緩濕疹、皮炎等問題。適量使用還能提升皮膚彈性與屏障功能，並提供天然的抗氧化保護。','乳油木果油（Shea Butter）又稱乳木果油或雪亞脂，是從非洲乳油木（Shea Tree）的果實種子中萃取而得的天然油脂，主要產於西非國家如布吉納法索、迦納等地。它質地柔軟厚實，在室溫下呈現乳白色固態，遇熱會融化，具有淡淡的堅果香氣。乳油木果油富含不飽和脂肪酸、維生素A、E及植物固醇，被廣泛應用於護膚品、護髮產品、唇膏及手工肥皂，也可少量用於食品及巧克力加工。相較於一般植物油，它的吸收性佳且滋潤度高，是天然保濕與修護的熱門成分。',1,'2026-05-28 10:32:58','2026-09-23 08:58:29');
INSERT  IGNORE INTO `oils` (`id`, `name`, `origin`, `benefits`, `suitable_for`, `is_active`, `created_at`, `updated_at`) VALUES (6,'蓖麻油','Castor Oil','麻油具有強烈的保濕與滲透力，能有效滋潤頭髮與皮膚，促進頭髮生長、改善乾燥分岔，並具一定抗菌與抗炎作用，常作為天然護膚與護髮成分。內服有強力通便（瀉藥）效果，但需謹慎使用，建議外用為主，避免過量攝取。','蓖麻油是從蓖麻（Ricinus communis）種子中冷壓或溶劑萃取而得的植物油，主要產地為印度、巴西、中國等地。它質地黏稠、顏色呈淡黃至無色，具有獨特的輕微氣味，在室溫下流動性較差。蓖麻油富含蓖麻油酸（Ricinoleic acid），這是其他植物油中罕見的高比例成分，因此具備優異的潤滑性與穩定性。廣泛應用於化妝品、護髮油、按摩油、肥皂製作，也常用於工業潤滑劑及醫藥用途。',1,'2026-05-28 10:37:08','2026-09-23 08:58:29');
INSERT  IGNORE INTO `oils` (`id`, `name`, `origin`, `benefits`, `suitable_for`, `is_active`, `created_at`, `updated_at`) VALUES (7,'芥花油','Rapeseed Oil','芥花油富含油酸與Omega-3脂肪酸，有助降低壞膽固醇（LDL）、提升好膽固醇（HDL），對心血管健康有益。適量食用還能提供抗氧化效果，幫助維持血脂平衡與整體代謝健康。','芥花油（Canola Oil）又稱菜籽油，是從低芥酸油菜籽中壓榨提煉而成的植物油，主要產地為加拿大、中國、澳洲等地。它顏色清澈淡黃，味道溫和清淡，幾乎沒有明顯氣味，是日常烹飪中最常見的食用油之一。芥花油的煙點高（約204°C），適合煎、炒、炸、烘焙等多種烹調方式，且流動性佳、性價比高，因此被廣泛應用於家庭與食品加工業。它含有較高比例的單元不飽和脂肪酸，是許多健康飲食推薦的烹調油。',1,'2026-05-29 05:55:19','2026-09-23 08:58:29');
INSERT  IGNORE INTO `oils` (`id`, `name`, `origin`, `benefits`, `suitable_for`, `is_active`, `created_at`, `updated_at`) VALUES (8,'紅棕櫚油','Red Palm Oil','紅棕櫚油富含β-胡蘿蔔素、維生素E及多酚類抗氧化物，有助提升免疫力、抗氧化，並支持眼睛與皮膚健康。適量食用可提供心血管保護與抗發炎效果，但因飽和脂肪含量較高，仍建議適度攝取。','紅棕櫚油（Red Palm Oil）是未經精煉、直接從油棕新鮮果肉中冷壓萃取的天然植物油，保留了豐富的天然類胡蘿蔔素，因此呈現鮮亮的紅橙色。它主要產於西非、馬來西亞、印尼等地，與一般精煉棕櫚油不同，風味更濃郁，帶有輕微的胡蘿蔔與果香氣息。紅棕櫚油煙點較高，適合煎炒、燉煮及油炸，在非洲傳統料理中被廣泛使用，也逐漸受到注重營養的消費者喜愛。相較於精煉棕櫚油，它保留了更多天然營養成分，但顏色與風味較為強烈。',1,'2026-05-29 06:03:51','2026-09-23 08:58:29');
INSERT  IGNORE INTO `oils` (`id`, `name`, `origin`, `benefits`, `suitable_for`, `is_active`, `created_at`, `updated_at`) VALUES (9,'棕櫚核仁油','Palm Kernel Oil','棕櫚核仁油富含月桂酸，具有良好的抗菌與保濕特性，能幫助滋潤皮膚與頭髮，並提供快速能量。適量使用可作為烹飪油或護膚成分，但因飽和脂肪含量高，長期大量攝取可能增加心血管負擔，建議適度使用。','櫚核仁油（Palm Kernel Oil）是從油棕果實內的核仁（種子）中壓榨萃取而得的植物油，與一般棕櫚油（來自果肉）來源不同。它主要產於馬來西亞、印尼等東南亞國家，呈現白色至淡黃色，在室溫下為固態，具有輕微的椰子香氣。棕櫚核仁油富含月桂酸（Lauric Acid）等中鏈飽和脂肪酸，穩定性高、氧化慢，常被用於烘焙、糖果、巧克力、咖啡奶精、油炸食品及人造奶油的生產，也廣泛應用於肥皂、洗髮精等清潔與護理產品。它的性質與椰子油較為相似，但價格通常更具優勢。',1,'2026-05-29 06:49:48','2026-09-23 08:58:29');
INSERT  IGNORE INTO `oils` (`id`, `name`, `origin`, `benefits`, `suitable_for`, `is_active`, `created_at`, `updated_at`) VALUES (10,'酪梨油','Avocado Oil','酪梨油富含單元不飽和脂肪酸（油酸）、維生素E及葉黃素，具有優異的抗氧化能力，有助保護心血管健康、降低壞膽固醇，並支持眼睛健康。外用時能深層滋潤皮膚、促進膠原蛋白生成，適合乾燥肌膚與抗老保養。','酪梨油（Avocado Oil）是從成熟酪梨果肉中冷壓萃取而成的植物油，主要產地為墨西哥、紐西蘭、澳洲、南非等地。它顏色呈現漂亮的翠綠色至淡黃綠色，具有溫和的堅果香氣與奶油般滑順口感。酪梨油的煙點極高（約250°C），非常適合高溫煎炒、烘焙與油炸，也可生食淋在沙拉上。相較於其他油脂，它質地輕盈卻滋潤度高，在烹飪與護膚領域都備受歡迎。',1,'2026-05-29 06:53:50','2026-09-23 08:58:29');
INSERT  IGNORE INTO `oils` (`id`, `name`, `origin`, `benefits`, `suitable_for`, `is_active`, `created_at`, `updated_at`) VALUES (11,'榛果油','Hazelnut Oil','榛果油含有豐富的維生素E、維生素B群及抗氧化物，有助保護心血管健康、降低壞膽固醇，並提供良好的抗氧化效果。外用時能深層滋潤皮膚、改善乾燥與細紋，適合乾性及成熟肌膚使用。','榛果油（Hazelnut Oil）是從榛果（榛仁）中冷壓萃取而成的優質植物油，主要產地為土耳其、義大利、美國等地。它顏色呈現淡金黃色，帶有濃郁的堅果香氣與細膩口感，風味豐富卻不油膩。榛果油富含單元不飽和脂肪酸，適合中低溫烹調、沙拉淋醬、烘焙甜點或製作醬料，也常被用於高端護膚與按摩油。相較於其他堅果油，它的香氣特別突出，能為料理增添優雅的堅果風味。',1,'2026-05-29 06:59:04','2026-09-23 08:58:29');
INSERT  IGNORE INTO `oils` (`id`, `name`, `origin`, `benefits`, `suitable_for`, `is_active`, `created_at`, `updated_at`) VALUES (12,'芝麻油','Sesame Oil','芝麻油富含芝麻素（Sesamin）、芝麻酚等強力抗氧化物，以及維生素E和不飽和脂肪酸，有助抗氧化、保護心血管並降低壞膽固醇。適量食用還能滋潤皮膚、改善乾燥，並具一定抗炎與保肝作用。','芝麻油是從芝麻種子中壓榨萃取而成的植物油，主要產地為中國、印度、緬甸及非洲部分地區，是亞洲料理中不可或缺的傳統油脂。它分為「冷壓生芝麻油」（顏色較淡、香氣溫和）與「熟壓芝麻油」（經烘焙後顏色呈深琥珀色，香氣濃郁強烈）。芝麻油具有獨特的堅果香氣，煙點適中，適合中低溫炒菜、涼拌、醬料調製及麻油雞等傳統料理，也常用於護膚與按摩。它的風味濃郁，少量使用即可為菜餚增添豐富層次。',1,'2026-05-29 07:02:48','2026-09-23 08:58:29');
INSERT  IGNORE INTO `oils` (`id`, `name`, `origin`, `benefits`, `suitable_for`, `is_active`, `created_at`, `updated_at`) VALUES (13,'米糠油','Rice Bran Oil','米糠油富含γ-穀維素（Oryzanol）、維生素E及植物固醇，具有優異的抗氧化能力，能有效降低壞膽固醇（LDL）、提升好膽固醇（HDL），對心血管健康特別有益。適量食用還有助調節血糖、改善皮膚狀況，並提供天然的抗發炎保護。','米糠油是從糙米的外層米糠（Rice Bran）中萃取而得的植物油，主要產地為印度、日本、泰國、中國及越南。它顏色呈現淡金黃色，氣味清淡、風味溫和，幾乎不影響食材原味。米糠油的煙點很高（約232°C），適合高溫煎炒、油炸及中式快炒，是亞洲家庭與餐廳常用的健康烹調油之一。近年因其獨特的營養成分，逐漸受到國際健康飲食市場的重視。',1,'2026-05-29 07:06:01','2026-09-23 08:58:29');
INSERT  IGNORE INTO `oils` (`id`, `name`, `origin`, `benefits`, `suitable_for`, `is_active`, `created_at`, `updated_at`) VALUES (14,'杏桃核仁油','Apricot Kernel Oil','杏桃核仁油富含油酸、亞油酸及維生素E，具有優異的保濕與滋潤效果，能有效改善皮膚乾燥、提升皮膚彈性，並具輕微抗氧化與抗炎作用。適量食用可補充健康不飽和脂肪酸，有助維持心血管健康與皮膚光澤。','杏桃核仁油（Apricot Kernel Oil）是從杏桃（杏子）的果核內仁中冷壓萃取而成的植物油，主要產地為土耳其、印度、中國等地。它顏色呈現淡金黃色，質地輕盈細滑，帶有溫和柔順的堅果香氣，味道清淡不搶戲。杏桃核仁油與甜杏仁油性質相似，但香氣更為細膩，適合中低溫烹調、沙拉淋醬，也廣泛應用於高端護膚品、按摩油、唇部護理及嬰兒油。它的吸收性佳、不易堵塞毛孔，是敏感肌與乾性肌的常用天然保養油。',1,'2026-05-29 07:08:41','2026-09-23 08:58:29');
INSERT  IGNORE INTO `oils` (`id`, `name`, `origin`, `benefits`, `suitable_for`, `is_active`, `created_at`, `updated_at`) VALUES (15,'蜜蠟','Beeswax','蜜蠟具有極佳的保濕鎖水能力，能在皮膚表面形成天然保護膜，減少水分流失，適合乾燥、敏感及受損肌膚使用。同時具輕微抗菌、抗炎與修護作用，可幫助舒緩皮膚發炎、促進傷口癒合，並提升產品的穩定性與滋潤度。','蜜蠟（Beeswax）是由蜜蜂腹部蠟腺分泌的天然蠟質，主要成分為酯類、脂肪酸與長鏈醇。它在室溫下為固態，顏色從淡黃到深黃不等，具有溫和的蜂蜜與蜂巢香氣，遇熱會融化，遇冷則凝固。蜜蠟被廣泛應用於天然護膚品（如唇膏、乳霜、護手霜）、手工蠟燭、木製品保養、食品塗層（如水果、乳酪）及醫藥用途。相較於石油衍生的蠟，蜜蠟更天然且具良好可塑性與乳化能力，是手工皂與保養品中常見的優質基底成分。',1,'2026-05-29 07:14:53','2026-09-23 08:58:29');
INSERT  IGNORE INTO `oils` (`id`, `name`, `origin`, `benefits`, `suitable_for`, `is_active`, `created_at`, `updated_at`) VALUES (16,'荷荷芭油','Jojoba Oil','荷荷芭油具有優異的保濕、平衡油脂分泌與修護能力，能有效改善乾燥、油性及痘痘肌膚問題，同時具抗炎與抗氧化效果。外用可軟化皮膚、減少細紋，並幫助頭髮順滑有光澤，是敏感肌與問題肌常用的天然保養成分。','荷荷芭油（Jojoba Oil）其實不是油，而是從荷荷芭（Jojoba）種子中冷壓萃取的液態蠟，主要產地為美國、墨西哥、以色列等地。它顏色呈現金黃色至淡黃色，質地輕盈、觸感絲滑，幾乎無味或帶有極淡的堅果香氣。荷荷芭油的化學結構與人類皮脂極為相似，因此吸收性極佳、不易氧化，保存期限可長達數年。廣泛應用於高端護膚品、按摩油、護髮產品、唇部保養及化妝品，也可少量用於料理。',1,'2026-05-29 07:21:58','2026-09-23 08:58:29');
INSERT  IGNORE INTO `oils` (`id`, `name`, `origin`, `benefits`, `suitable_for`, `is_active`, `created_at`, `updated_at`) VALUES (17,'澳洲胡桃油','Macadamia Oil','澳洲胡桃油含有豐富的維生素E、植物固醇及抗氧化物，有助保護心血管健康、降低壞膽固醇，並提供良好的抗氧化效果。外用時能深層滋潤皮膚、提升彈性、改善乾燥與細紋，特別適合成熟肌與乾性肌使用。','澳洲胡桃油（Macadamia Oil）是從澳洲胡桃（Macadamia nut）果仁中冷壓萃取而成的優質植物油，主要產地為澳洲、夏威夷、南非等地。它顏色呈現淡金黃色，質地輕盈絲滑，帶有溫和細膩的堅果香氣，風味豐富卻不濃烈。澳洲胡桃油富含單元不飽和脂肪酸（尤其是油酸），煙點較高（約210°C），適合中高溫烹調、烘焙、沙拉淋醬，也廣泛應用於高端護膚與按摩油。相較於其他堅果油，它的穩定性佳且氧化速度慢，保存期限較長。',1,'2026-05-30 01:16:38','2026-09-23 08:58:29');
INSERT  IGNORE INTO `oils` (`id`, `name`, `origin`, `benefits`, `suitable_for`, `is_active`, `created_at`, `updated_at`) VALUES (18,'山茶花油','Camellia Oil','山茶花油具有優異的抗氧化能力，能幫助降低壞膽固醇、保護心血管健康，並具抗發炎效果。適量食用還能滋潤皮膚、提升皮膚彈性與光澤度，是兼具食用與護膚雙重價值的天然油脂。','山茶花油又稱茶籽油，是從油茶樹（Camellia oleifera）種子中冷壓萃取而成的植物油，主要產地為中國南方（如江西、湖南、廣西）。它顏色呈現清澈淡金黃色，氣味清淡溫和，帶有極輕的堅果香氣，風味優雅不搶戲，被譽為「東方橄欖油」。山茶花油富含單元不飽和脂肪酸（油酸含量高達75-85%），煙點高（約252°C），非常適合高溫煎炒、油炸、烘焙及生食淋醬。長期以來是中國傳統養生料理與高端烹飪的首選油脂之一。',1,'2026-05-30 01:18:28','2026-09-23 08:58:29');
INSERT  IGNORE INTO `oils` (`id`, `name`, `origin`, `benefits`, `suitable_for`, `is_active`, `created_at`, `updated_at`) VALUES (19,'開心果油','Pistachio Oil','開心果油含有豐富的維生素E、葉黃素及抗氧化物，有助保護心血管健康、降低壞膽固醇，並提供良好的抗氧化與抗炎效果。外用時能深層滋潤皮膚、改善乾燥與細紋，適合成熟肌與乾性肌保養。','開心果油（Pistachio Oil）是從開心果果仁中冷壓萃取而成的優質堅果油，主要產地為伊朗、美國、土耳其等地。它呈現漂亮的鮮綠色至深綠色，具有濃郁的堅果香氣與豐富的果仁風味，是所有堅果油中香氣最突出的之一。開心果油富含單元不飽和脂肪酸，煙點適中，適合中低溫烹調、沙拉淋醬、義式料理、甜點及醬料製作，也常用於高端護膚與按摩油。它的顏色與風味獨特，能為菜餚增添優雅的堅果層次感。',1,'2026-05-30 01:25:26','2026-09-23 08:58:29');
INSERT  IGNORE INTO `oils` (`id`, `name`, `origin`, `benefits`, `suitable_for`, `is_active`, `created_at`, `updated_at`) VALUES (20,'可可脂','Cocoa Butter','可可脂具有極佳的保濕與鎖水能力，能在皮膚表面形成保護膜，有效改善乾燥、粗糙及唇部乾裂，適合敏感與乾燥肌膚使用。同時含有天然抗氧化物，可幫助提升皮膚彈性與柔軟度，並具輕微抗炎修護作用。','可可脂（Cocoa Butter）是從可可豆中壓榨萃取而得的天然植物油脂，主要產地為象牙海岸、迦納、印尼等西非及熱帶地區。它在室溫下呈現白色至淡黃色的固態，具有溫和的可可香氣，體溫下會自然融化，擁有良好的可塑性與滑順質地。可可脂是製作巧克力的核心原料，也廣泛應用於護唇膏、身體乳霜、肥皂及護膚產品中。它富含天然對稱性脂肪酸（硬脂酸、棕櫚酸、油酸），穩定性高，不易氧化。',1,'2026-05-30 11:02:54','2026-09-23 08:58:29');
INSERT  IGNORE INTO `oils` (`id`, `name`, `origin`, `benefits`, `suitable_for`, `is_active`, `created_at`, `updated_at`) VALUES (21,'玫瑰果油','Rosehip Oil','玫瑰果油具有強大的抗氧化與修護能力，能有效淡化疤痕、改善色素沉澱、促進膠原蛋白生成，特別適合抗老化、乾燥肌與問題肌膚使用。適量外用可提升皮膚彈性、亮度與平滑度，也具輕微抗炎效果。','玫瑰果油（Rosehip Oil）是從野生玫瑰（Rosa canina）的果實種子中冷壓萃取而成的珍貴植物油，主要產地為智利、南非及歐洲部分地區。它呈現獨特的橙紅色至深紅色，質地輕盈，帶有淡淡的天然果香。玫瑰果油富含亞油酸、α-亞麻酸等必需脂肪酸，以及高含量的維生素A（視黃醇）、維生素C與維生素E，是護膚領域的明星成分，也可少量用於高端料理。相較於一般植物油，它氧化速度較快，建議冷藏保存並盡快使用。',1,'2026-05-30 12:01:43','2026-09-23 08:58:29');
INSERT  IGNORE INTO `oils` (`id`, `name`, `origin`, `benefits`, `suitable_for`, `is_active`, `created_at`, `updated_at`) VALUES (22,'橄欖脂','Olive Butter','橄欖脂保濕與鎖水能力極強，能有效改善皮膚乾燥、粗糙與緊繃感，適合乾性、敏感及成熟肌膚使用。同時具抗氧化與柔軟皮膚的作用，可幫助提升肌膚彈性並提供天然保護屏障。','橄欖脂（Olive Butter）是從橄欖油中萃取或以橄欖果實為基底，經過特殊加工製成的濃稠天然油脂（Butter），質地比橄欖油更厚實柔軟。它呈現乳白色至淡黃色，具有溫和的橄欖果香，室溫下為固態，遇熱易融化。橄欖脂富含油酸、角鯊烷及天然植物固醇，常作為護膚品、乳霜、唇膏、身體乳及手工肥皂的基底成分，也可少量用於烘焙與料理中。其滋潤度高、吸收性佳，是替代乳木果油的溫和選擇。',1,'2026-05-30 12:05:31','2026-09-23 08:58:29');
INSERT  IGNORE INTO `oils` (`id`, `name`, `origin`, `benefits`, `suitable_for`, `is_active`, `created_at`, `updated_at`) VALUES (23,'葵花油','Sunflower Oil','葵花油富含維生素E與亞油酸（Omega-6），具有良好的抗氧化能力，有助保護細胞、維持皮膚健康，並可幫助降低壞膽固醇。適量食用有益心血管，但因Omega-6含量較高，建議與富含Omega-3的油脂搭配使用，以維持脂肪酸平衡。','葵花油是從葵花籽中壓榨萃取而成的植物油，主要產地為俄羅斯、烏克蘭、阿根廷、中國及歐洲多國，是全球最常見的食用油之一。它顏色清澈淡黃，氣味清淡，幾乎無明顯味道，不會影響食材原味。葵花油分為普通型（富含亞油酸）與高油酸型（單元不飽和脂肪酸較高），煙點較高（約232°C），適合煎炒、油炸、烘焙及涼拌等多種烹調方式。它的性價比高、流動性佳，是家庭與食品工業廣泛使用的日常烹飪油。',1,'2026-05-30 12:12:04','2026-09-23 08:58:29');
INSERT  IGNORE INTO `oils` (`id`, `name`, `origin`, `benefits`, `suitable_for`, `is_active`, `created_at`, `updated_at`) VALUES (24,'大豆油','Soybean Oil','大豆油含有豐富的亞油酸與維生素E，有助提供必需脂肪酸、維持細胞膜健康，並具一定抗氧化作用。適量食用可幫助降低壞膽固醇，但因Omega-6含量較高，建議與富含Omega-3的油脂搭配使用，以維持脂肪酸平衡。','大豆油是從大豆中壓榨或溶劑萃取而成的植物油，是全球產量最大、消耗最廣的食用油之一，主要產地為美國、巴西、阿根廷及中國。它顏色呈現淡黃色至金黃色，氣味清淡、味道中性，幾乎不會影響食材原味。 大豆油煙點較高（約230°C），適合高溫油炸、煎炒、烘焙及加工食品，也常用於沙拉油及調和油。大豆油富含多元不飽和脂肪酸（Omega-6），性價比高，是許多家庭與食品工業的常用烹調油。 功效',1,'2026-05-30 12:13:28','2026-09-23 08:58:29');
INSERT  IGNORE INTO `oils` (`id`, `name`, `origin`, `benefits`, `suitable_for`, `is_active`, `created_at`, `updated_at`) VALUES (25,'白油','White Oil','白油主要作為強效保濕鎖水劑，能在皮膚表面形成保護膜，有效減少水分流失，適合極乾、敏感或受損肌膚使用。外用安全穩定，但它無法被皮膚吸收，僅提供物理性保護，長期大量使用建議搭配其他滋潤成分。','白油（White Oil / Mineral Oil）又稱礦物油或液態石蠟，是由石油提煉後高度精製而成的無色透明油脂，幾乎無味、無臭。它質地輕盈、穩定性極高，不易氧化變質，在室溫下為液態。白油被廣泛應用於化妝品、護膚品、嬰兒油、按摩油、食品加工（例如糖果塗層）、醫藥及工業潤滑用途。因其純度高且成本低廉，是許多產品中常用的基底油或隔離成分。',1,'2026-05-30 12:15:32','2026-09-23 08:58:29');
INSERT  IGNORE INTO `oils` (`id`, `name`, `origin`, `benefits`, `suitable_for`, `is_active`, `created_at`, `updated_at`) VALUES (26,'葡萄籽油','Grapeseed Oil','葡萄籽油含有豐富的維生素E、原花青素等強力抗氧化物，有助抵抗自由基、保護心血管，並可降低壞膽固醇。外用時能滋潤皮膚、改善彈性、淡化細紋，適合油性及混合肌膚使用，具有抗炎與抗老化效果。','葡萄籽油是從葡萄酒釀造後的葡萄籽中冷壓或萃取而得的植物油，主要產地為義大利、法國、西班牙、美國及南非。它顏色呈現淡黃至淡綠色，質地輕盈，氣味清淡、幾乎無味，風味中性，不易搶走食材原味。葡萄籽油富含多元不飽和脂肪酸（亞油酸），煙點較高（約216°C），適合高溫煎炒、油炸、烘焙及生食沙拉淋醬，也廣泛應用於護膚品與按摩油。它的吸收性佳，是日常烹飪與美容保養的熱門選擇。',1,'2026-05-30 12:16:54','2026-09-23 08:58:29');
INSERT  IGNORE INTO `oils` (`id`, `name`, `origin`, `benefits`, `suitable_for`, `is_active`, `created_at`, `updated_at`) VALUES (27,'花生油','Peanut Oil','花生油富含單元不飽和脂肪酸（油酸）與維生素E，有助降低壞膽固醇、保護心血管健康，並提供抗氧化保護。適量食用有益皮膚健康，但因含有較多Omega-6脂肪酸，建議與富含Omega-3的油類交替使用，以維持脂肪酸平衡。','花生油是從花生種子中壓榨萃取而成的植物油，主要產地為中國、印度、美國及非洲國家，是亞洲家庭最常使用的傳統食用油之一。它顏色呈現淡黃至金黃色，根據加工方式分為冷壓花生油與熱壓（烘焙）花生油，其中熱壓花生油具有濃郁香氣，深受中式料理喜愛。花生油煙點高（約230°C），耐高溫、不易氧化，適合爆炒、油炸、煎炸及中式快炒等高溫烹調。它的風味香醇，能為菜餚增添特有花生香氣，是製作宮保雞丁、油炸食品及傳統小吃的常用油。',1,'2026-05-30 12:18:34','2026-09-23 08:58:29');
INSERT  IGNORE INTO `oils` (`id`, `name`, `origin`, `benefits`, `suitable_for`, `is_active`, `created_at`, `updated_at`) VALUES (28,'芒果脂','Mango Butter','芒果脂具有極佳的保濕、柔軟與修護能力，能有效改善皮膚乾燥、粗糙及龜裂，特別適合乾燥肌、敏感肌與冬季保養使用。同時具抗氧化與輕微抗炎效果，可幫助提升皮膚彈性、舒緩不適，並提供天然保護屏障。','芒果脂（Mango Butter）又稱芒果果仁脂，是從芒果種子（果核）中冷壓萃取而得的天然植物油脂，主要產地為印度、非洲及巴西等芒果盛產地區。它在室溫下呈現乳白色至淡黃色的固態，具有溫和的果香氣，遇熱會軟化融化，質地細膩柔軟，類似乳木果油的可塑性。芒果脂富含硬脂酸、油酸等脂肪酸，穩定性佳，被廣泛應用於高端護膚品、身體乳、唇膏、護髮產品及手工肥皂，也可少量用於食品及巧克力替代可可脂。它的吸收性良好且不油膩，是天然保養品中受歡迎的滋潤成分。',1,'2026-05-30 12:21:14','2026-09-23 08:58:29');
INSERT  IGNORE INTO `oils` (`id`, `name`, `origin`, `benefits`, `suitable_for`, `is_active`, `created_at`, `updated_at`) VALUES (29,'月見草油','Evening Primrose Oil','月見草油具有良好的抗炎與荷爾蒙調節作用，有助改善女性經前症候群（PMS）、更年期不適及皮膚炎症問題（如濕疹、異位性皮膚炎）。同時能滋潤皮膚、提升肌膚彈性，並提供抗氧化保護，適合乾性及敏感肌使用。','月見草油（Evening Primrose Oil）是從月見草（Evening Primrose）種子中冷壓萃取而成的植物油，主要產地為歐洲、北美及中國。它呈現淡黃色至金黃色，質地輕盈，帶有輕微的草本氣味。月見草油富含γ-次亞麻油酸（GLA），這是一種稀有的Omega-6脂肪酸，因此在保健食品與護膚領域備受重視。常以膠囊形式作為營養補充劑，也廣泛應用於高端護膚品、按摩油及頭髮護理產品中，適合內服與外用。 功效',1,'2026-05-30 12:22:27','2026-09-23 08:58:29');
INSERT  IGNORE INTO `oils` (`id`, `name`, `origin`, `benefits`, `suitable_for`, `is_active`, `created_at`, `updated_at`) VALUES (30,'小麥胚芽油','Wheat Germ Oil','小麥胚芽油含有極高的天然維生素E與抗氧化物，能有效對抗自由基、延緩老化，並有助維持心血管健康與皮膚彈性。適量食用或外用可改善皮膚乾燥、促進傷口癒合，並支持免疫系統與荷爾蒙平衡，尤其適合想補充維生素E的人使用。','小麥胚芽油（Wheat Germ Oil）是從小麥胚芽（小麥粒中最具營養的部分）中冷壓萃取而成的植物油，主要產地為美國、加拿大、歐洲及中國。它呈現金黃色至琥珀色，具有濃郁的麥香與堅果風味，質地較為濃稠。小麥胚芽油是天然維生素E含量最高的食用油之一，也富含多種不飽和脂肪酸與微量元素，但因多元不飽和脂肪酸比例高，穩定性較低，氧化速度較快，建議冷藏保存並盡快使用。它適合低溫烹調、沙拉淋醬、果昔或作為保健補充油，也廣泛應用於護膚與護髮產品。',1,'2026-05-30 12:25:33','2026-09-23 08:58:29');
INSERT  IGNORE INTO `oils` (`id`, `name`, `origin`, `benefits`, `suitable_for`, `is_active`, `created_at`, `updated_at`) VALUES (31,'油菜籽油','Rapeseed Oil','油菜籽油富含單元不飽和脂肪酸（油酸）與Omega-3脂肪酸，有助降低壞膽固醇、保護心血管健康，並維持血脂平衡。適量食用能提供抗氧化效果，但傳統高芥酸品種需注意攝取量，建議選擇低芥酸的芥花油更為安全。','油菜籽油（Rapeseed Oil）是從油菜籽中壓榨萃取而成的植物油，是全球重要的食用油來源之一，主要產地為中國、加拿大、印度及歐洲各國。傳統油菜籽油含有較高芥酸，經過現代育種後，低芥酸品種即為我們常見的「芥花油（Canola Oil）」。油菜籽油顏色淡黃、清澈，氣味溫和，煙點高（約230-240°C），適合各種烹調方式，包括煎、炒、炸、烘焙等。因性價比高且用途廣泛，是許多家庭與食品加工業常用的基礎烹飪油。',1,'2026-05-30 12:28:28','2026-09-23 08:58:29');
INSERT  IGNORE INTO `oils` (`id`, `name`, `origin`, `benefits`, `suitable_for`, `is_active`, `created_at`, `updated_at`) VALUES (32,'紅花籽油','Safflower Seed Oil','紅花籽油富含亞油酸等必需脂肪酸，有助降低壞膽固醇（LDL）、改善血脂平衡，並提供抗氧化效果。高油酸型紅花籽油對心血管保護更佳，但整體Omega-6含量較高，建議與富含Omega-3的油脂交替使用。','紅花籽油是從紅花（Safflower）種子中壓榨或萃取而成的植物油，主要產地為印度、美國、墨西哥及中國。它顏色清澈淡黃，氣味與味道極為清淡，幾乎不影響食材原味。紅花籽油分為高亞油酸型（多元不飽和脂肪酸高）與高油酸型（單元不飽和脂肪酸高），煙點高（約250-260°C），適合高溫油炸、煎炒、烘焙及生食沙拉淋醬，是日常烹飪與食品加工中常用的健康油脂之一。',1,'2026-05-30 12:30:50','2026-09-23 08:58:30');
INSERT  IGNORE INTO `oils` (`id`, `name`, `origin`, `benefits`, `suitable_for`, `is_active`, `created_at`, `updated_at`) VALUES (33,'苦茶油','Camellia Seed Oil','苦茶油富含單元不飽和脂肪酸與天然抗氧化物，有助降低壞膽固醇、保護心血管健康，並具抗發炎與抗氧化效果。適量食用還能滋潤皮膚、提升肌膚彈性，是兼具食用與護膚價值的優質油脂。','苦茶油又稱苦茶籽油，是從苦茶樹（Camellia oleifera）的種子中冷壓萃取而成的傳統植物油，主要產於台灣、中國南方（如湖南、江西）。它顏色呈現清澈的金黃色，氣味清香溫和，帶有淡淡的茶籽香氣，風味優雅不油膩。苦茶油油酸含量高達75-85%，煙點極高（約252°C），非常適合高溫煎炒、油炸、燉煮及生食淋醬，在台灣被視為養生聖品，與山茶花油同屬一類，但苦茶油在台灣更強調傳統製法與純度。',1,'2026-05-30 12:32:16','2026-09-23 08:58:30');
INSERT  IGNORE INTO `oils` (`id`, `name`, `origin`, `benefits`, `suitable_for`, `is_active`, `created_at`, `updated_at`) VALUES (34,'水蜜桃核仁油','Peach Kernel Oil','水蜜桃核仁油富含油酸、亞油酸及維生素E，具有優異的保濕與滋潤效果，能有效改善皮膚乾燥、粗糙，提升皮膚柔軟度與彈性。同時具輕微抗氧化與抗炎作用，適合乾燥、敏感及成熟肌膚使用，也可幫助淡化細紋與促進肌膚修護。','水蜜桃核仁油（Peach Kernel Oil）是從水蜜桃果核內的仁中冷壓萃取而成的天然植物油，主要產地為中國、義大利、西班牙及美國等水蜜桃盛產地區。它顏色呈現淡金黃色，質地極為輕盈細滑，帶有溫和清新的果仁香氣，吸收性極佳，不易油膩。水蜜桃核仁油與甜杏仁油、杏桃核仁油性質相近，但香氣更柔和細膩，適合中低溫烹調、沙拉淋醬，也廣泛應用於高端護膚品、按摩油、唇部保養及嬰兒護理產品。它的滲透力強，是敏感肌與乾性肌常用的天然保養油。',1,'2026-05-30 12:33:44','2026-09-23 08:58:30');
INSERT  IGNORE INTO `oils` (`id`, `name`, `origin`, `benefits`, `suitable_for`, `is_active`, `created_at`, `updated_at`) VALUES (35,'亞麻仁油','Flaxseed Oil','亞麻仁油富含Omega-3，能有效抗發炎、幫助降低血脂、保護心血管，並可改善乾性皮膚與頭髮健康。適量攝取還有助平衡荷爾蒙、支持大腦功能與腸道健康，但不建議加熱食用。','亞麻仁油（Flaxseed Oil）是從亞麻植物種子中冷壓萃取而成的植物油，主要產地為加拿大、美國、中國及印度。它呈現金黃至淡琥珀色，質地輕薄，具有輕微的堅果香氣與草本風味。亞麻仁油是植物界中Omega-3脂肪酸（α-亞麻酸 ALA）含量最高的油脂之一，但煙點很低（約107°C），不適合高溫烹調，最適合生食淋醬、拌沙拉、優格或加入果昔中。由於極易氧化，必須冷藏保存並盡快使用，也常做成軟膠囊作為營養補充劑。',1,'2026-05-30 12:35:11','2026-09-23 08:58:30');
INSERT  IGNORE INTO `oils` (`id`, `name`, `origin`, `benefits`, `suitable_for`, `is_active`, `created_at`, `updated_at`) VALUES (36,'琉璃苣油','Borage Oil','琉璃苣油富含γ-次亞麻油酸（GLA），具有強大的抗炎作用，有助改善異位性皮膚炎、濕疹、經前症候群及更年期不適。同時能提升皮膚保濕度、改善乾燥與敏感問題，並幫助平衡荷爾蒙與緩解關節不適。','琉璃苣油（Borage Oil）又稱星花油，是從琉璃苣（Borago officinalis）種子中冷壓萃取而成的植物油，主要產地為歐洲、北美及紐西蘭。它呈現淡黃色至金黃色，質地輕盈，幾乎無明顯氣味。琉璃苣油是自然界中γ-次亞麻油酸（GLA）含量最高的油脂之一，遠高於月見草油，因此在保健與美容領域備受重視。常以膠囊形式作為營養補充劑，也廣泛應用於高端護膚品、按摩油及頭髮護理產品中。',1,'2026-05-30 12:37:21','2026-09-23 08:58:30');
INSERT  IGNORE INTO `oils` (`id`, `name`, `origin`, `benefits`, `suitable_for`, `is_active`, `created_at`, `updated_at`) VALUES (37,'豬油','Lard Oil','豬油含有豐富的飽和脂肪酸與單元不飽和脂肪酸，能提供高熱量與穩定能量，也含有少量維生素D。適量使用可提升菜餚風味，但因飽和脂肪含量較高，建議減少過量攝取，以維護心血管健康。','豬油（Lard）是從豬腹部或背部脂肪組織提煉而成的動物油脂，是傳統中式料理中非常重要的烹調油之一。它在室溫下呈現白色固態，具有濃郁的豬肉香氣，經過煉製後可分為板油（較純）和肥肉煉製的豬油，後者香氣更為濃厚。豬油煙點高（約190-200°C），耐高溫且熱傳導性佳，非常適合爆炒、煎炸、炒飯及製作傳統中式糕點（如鳳梨酥、老婆餅）。其風味獨特，能為菜餚增添香醇口感，是許多老一輩廚師堅持使用的經典油脂。',1,'2026-05-30 12:38:46','2026-09-23 08:58:30');
